import json, re, random, sys
d = json.load(open(sys.argv[1], encoding='utf-8')); t3, t5 = d["t3"], d["t5"]
stem = sys.argv[3]
SUB = ["E1","E2","E3","F1","F2"]
alias = {"Bryum billardierei":"Bryum billardieri","Acaena novae zelandiae":"Acaena novae-zelandiae","Isolepis indundata":"Isolepis inundata","Drosera whittakerii":"Drosera whittakeri"}
t5 = [x for x in t5 if x["name"] != "Tall shrubs"]
REG = {"St1":"stems","L1":"lignotubers","Rsk1":"root suckers","R1":"rhizomes","T1":"tubers","Tu1":"tuberoids"}
F = "fire_response categorical_surv1"
src = "Wark, M. C. (1997). Regeneration of some forest and gully communities in the Angahook-Lorne State Park (north-eastern Otway Ranges) 1-10 years after the wildfire of February 1983. Proceedings of the Royal Society of Victoria, 109(1), 7-36."
pw = ("fire_response categorical_surv1 from Table 5 regeneration strategy groups (terminology follows Purdie 1977a, 1977b; p. 10, 29): OSR = obligate seed regenerator (regenerating from seed or propagules only) -> obligate; FRR = facultative regrowth regenerator (regenerating by regrowth, and from seed or propagules) -> resprouter; ORR = obligate regrowth regenerator (regenerating by regrowth only) -> resprouter; "
      "Table 5 key (p. 29): S1, S2, S3 = germinated from seed year 1, 2, 3; R1 = regrowth from rhizomes, T1 = from tubers, Tu = from tuberoids, L1 = from lignotubers, St1 = from stems, Rsk1 = from root suckers, year 1; F1, F2, F3 = first flowered year 1, 2, 3 after fire; seed used to mean both seeds and spores; "
      "Table 5 covers forest and gully communities 1-3 years after fire, values not split by subsite; Location_name = subsites where the taxon was recorded in Table 3 (p. 13-19, any of years 1, 3, 10); "
      "sites (Table 1, p. 8): E (Bambra Road, Angahook-Lorne State Park; subsites E1 and E2 Eucalyptus tricarpa open-forest, E3 gully complex) and F (near Distillery Creek Road, Angahook-Lorne State Park; subsite F1 gully complex, F2 modified gully complex), near Aireys Inlet, Victoria; no coordinates given; "
      "Rainfall_mm = annual mean rainfall of Anglesea 657 mm (1982 total 452 mm) (p. 9); fire: Ash Wednesday wildfire of 17 February 1983, high-intensity, destroyed all ground strata and crown-fired the overstorey at all subsites (p. 9); Fire_season_categorical derived from fire date 17 February 1983; at subsite F2 a peat fire started by the wildfire burnt for 3 months (p. 9)")
not3 = {"Eucalyptus aromaphloia","Eucalyptus cypellocarpa","Eucalyptus globulus ssp. bicostata","Eucalyptus ovata","Eucalyptus viminalis","Acacia dealbata","Acacia mearnsii","Acacia melanoxylon","Pomaderris aspera","Pomaderris ferruginea","Prostanthera lasianthos","Exocarpos cupressiformis"}
five_m = {"Acianthus pusillus","Eriochilus cucullatus","Pterostylis parviflora","Drosera whittakerii","Lagenifera gracilis"}
bryo = {"Lichens","Liverworts","Mosses"}
rows = []; log = []
for x in t5:
    n5 = x["name"]; n3 = alias.get(n5, n5)
    ents = t3.get(n3, [])
    pres = set(); fam = ""; intro = x["intro"]
    for e in ents:
        pres |= set(e["pres"]); fam = fam or e["family"]; intro = intro or e["intro"]
    if n5 == "Amyema pendulum": pres = {"E1","E2"}
    if n5 == "Hymenophyllum cupressiforme": pres = {"F1"}
    loc = "; ".join(s for s in SUB if s in pres)
    parts = n3.split(); g = parts[0]; sp = parts[1]; subsp = ""
    notes = [f"Table 5, p. {x['page']+6}"]
    if len(parts) > 2:
        subsp = "subsp. " + parts[-1]; notes.append(f"subsp printed as '{' '.join(parts[2:])}'")
    if n5 != n3: notes.append(f"name printed as '{n5}' in Table 5 and '{n3}' in Table 3; Species follows Table 3")
    if intro: notes.append("native_status from '*' = introduced species (Table 3 key, p. 19)")
    strat, fl = x["strategy"], x["flower"]
    notes.append(f"{x['group']}; regeneration strategy printed as '{strat}'; first flowering printed as '{fl if fl else 'blank'}'")
    if n5 == "Marchantia polymorpha": notes.append("text (p. 10): species described as Marchantia polymorpha in Wark et al. 1987 was in fact Marchantia berteroana; tables keep Marchantia polymorpha")
    if x["group"] == "OSR": fr = "obligate"
    else: fr = "resprouter"
    rtype = "; ".join(dict.fromkeys(REG[c.strip(",")] for c in strat.split() if c.strip(",") in REG))
    m = re.findall(r"F(\d)", fl); unc = "?" in fl
    val = ""
    if fl == "F1 or F2": val = "1-2"
    elif m: val = m[0]
    if unc and m: notes.append("first flowering printed with '?' (uncertain)")
    if strat in ("?", "? ?"): notes.append("regeneration strategy and flowering printed as '?'; present before the fire but not recorded 1-10 years after fire (Table 5 key, Table 3 legend)")
    r = {"Genus":g,"Species":sp,"subsp":subsp,"scientific_name":f"{g} {sp}","native_status":"introduced" if intro else "","Family":fam.capitalize() if fam else "",
         F:fr,"resprouter_type":rtype if fr=="resprouter" else "","Location_name":loc,"Rainfall_mm":"657","Fire_type":"wildfire","Fire_season_categorical":"Summer","Fire_severity_categorical":"High","Source":src,"File_name":stem}
    if x["lifeform"] in bryo and x["group"]=="OSR":
        if val: notes.append(f"non-vascular plant: first flowering code means first produced spores in year {val}; not a flowering time, so time columns not filled")
    elif x["group"] == "OSR":
        if val: r["Age at first flower production from seed_repr3"] = val; notes.append("Age at first flower production from seed_repr3 = Table 5 first flowering year of plants regenerating from seed only")
        if n5 in not3: r["Age at first flower production from seed_repr3"] = ">3"; notes.append("Age at first flower production from seed_repr3: not flowering at year 3, all 12 such species flowered by 10 years post-fire (text, p. 31)")
    elif x["group"] == "ORR":
        if val: r["Time to first flower production resprout_repr3a"] = val; notes.append("Time to first flower production resprout_repr3a = Table 5 first flowering year of plants regenerating by regrowth only")
    else:
        if val: notes.append(f"first flowered year {val} after fire; not stated whether from resprouts or seedlings (FRR), so time columns not filled")
        if n5 in not3: notes.append("not flowering at year 3, flowered by 10 years post-fire (text, p. 31); not stated whether from resprouts or seedlings")
    if n5 == "Lomatia ilicifolia":
        r["Time to first flower production resprout_repr3a"] = "0.5-0.667"
        notes.append("Time to first flower production resprout_repr3a from text (p. 31): flowered on new regrowth at 6-8 months, rarely seen to flower except after fire; Time to first flower production resprout_repr3a converted from 6-8 months")
    if n5 in five_m: notes.append("text (p. 30): flowered from 5 months post-fire")
    if n5 in ("Goodenia ovata","Epacris impressa"): notes.append("text (p. 31): juvenile phase brief, flowering within 2 years on plants only a few centimetres high")
    if n5 in ("Goodenia ovata","Pimelea humilis","Lomatia ilicifolia"): notes.append("text (p. 31): one of three shrubs that flowered in the first year")
    if fr == "resprouter" and not rtype: pass
    r["Notes"] = "; ".join(notes + [pw])
    rows.append(r)
json.dump(rows, open(sys.argv[2], 'w'), ensure_ascii=False)
print(len(rows), "rows")
random.seed(7)
for r in random.sample(rows, 3):
    print({k: v for k, v in r.items() if k not in ("Notes","Source","File_name") and v})
